class Solution {
    private int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int[][] id = new int[n][n];
        java.util.Map<Integer, Integer> area = new java.util.HashMap<>();
        int label = 2, result = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1 && id[i][j] == 0) {
                    int size = dfs(grid, id, i, j, label, n);
                    area.put(label, size);
                    result = Math.max(result, size);
                    label++;
                }
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 0) {
                    java.util.Set<Integer> seen = new java.util.HashSet<>();
                    int total = 1;
                    for (int[] d : dirs) {
                        int ni = i + d[0], nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < n && id[ni][nj] > 0 && seen.add(id[ni][nj]))
                            total += area.get(id[ni][nj]);
                    }
                    result = Math.max(result, total);
                }
        return result;
    }
    private int dfs(int[][] grid, int[][] id, int r, int c, int label, int n) {
        if (r < 0 || r >= n || c < 0 || c >= n || grid[r][c] != 1 || id[r][c] != 0) return 0;
        id[r][c] = label;
        int size = 1;
        for (int[] d : dirs) size += dfs(grid, id, r + d[0], c + d[1], label, n);
        return size;
    }
}
